/* Types */
/**  `AppError` as the frontend receives it (the `Serialize` above), for the bindings. */
export type AppError = {
	kind: ErrorKind,
	message: string,
};

export type Count = {
	label: string,
	/**  Second line (an album's artist…). */
	detail: string | null,
	count: number,
};

/**
 *  The cover shown for a title (`title` as in `NowPlaying.title`, so the window can tell it is
 *  still the track on air).
 */
export type Cover = {
	title: string | null,
	url: string | null,
	/**  `url` is the station's logo, not the track's cover art. */
	logo: boolean,
};

export type CoverSource = {
	id: SourceId,
	enabled: boolean,
};

/**  One list, as published. */
export type CuratedList = {
	id: string,
	title: string,
	description: string,
	curators: string[],
	use?: string[],
	genres?: string[],
	countries?: string[],
	items: Item[],
};

export type CustomService = {
	/**  `custom:…`, stored among the enabled ids (a comma-separated list). */
	id: string,
	name: string,
	/**  Search address, `{query}` standing for the encoded track. */
	template: string,
};

/**  A station's donation page, as the player shows it. */
export type DonationLink = {
	url: string,
	/**  Where the money goes, shown next to the link: `helloasso.com`. */
	domain: string,
};

/**  [`AppError::kind`]. */
export type ErrorKind = "database" | "network" | "catalog" | "io" | "other";

/**
 *  The events sent to the windows, by name, with their payload: the front end listens to
 *  them through this map (`listen` in `api.ts`). `null` is an event without payload.
 */
export type EventPayloads = {
	"player:state": PlayerState,
	"player:now-playing": NowPlaying,
	"player:cover": Cover,
	"player:muted": boolean,
	"player:title-status": TitleStatus,
	"player:station": StationChange,
	"recipes:notice": RecipeNotice,
	"favorite:gone": string,
	"favorites:changed": null,
	"donations:updated": null,
	"lists:updated": null,
	"share:opened": null,
	"updates:available": null,
};

export type ExportedFile = {
	path: string,
	/**  File name alone, for a short notice. */
	file_name: string,
	count: number,
};

export type Favorite = {
	station_id: string,
	name: string,
	stream_url: string,
	genre: string | null,
	added_at?: string | null,
};

export type Format = "csv" | "json";

/**  Health status of a station, as known to the catalog. */
export type Health = { status: "ok" } | 
/**
 *  The catalog's last check failed. May be a false negative (brief outage,
 *  geo-blocking of the checking servers): playback is still allowed.
 */
{ status: "unreachable"; last_ok: string | null } | 
/**  Cannot be played by our engine (HLS for now). */
{ status: "unsupported"; reason: string };

export type HistoryEntry = {
	id: number,
	station_id: string,
	/**
	 *  The name the user gave the station, else the name at the time of listening (for old rows,
	 *  the favorite or personal station name if known).
	 */
	station_name: string | null,
	/**  Raw title as announced on air. */
	track_title: string,
	artist: string | null,
	title: string,
	track_key: string,
	played_at: string,
	liked: boolean,
	/**  Artist and title cleaned for a music service's search box. */
	search_query: string,
};

/**  Size of the history, for the settings. */
export type HistorySummary = {
	count: number,
	/**  Oldest entry (`YYYY-MM-DD HH:MM:SS`, UTC), if any. */
	since: string | null,
};

export type Identification = {
	enabled: boolean,
	/**  Liked tracks (in the period) identified on MusicBrainz, not found, or not looked up yet. */
	matched: number,
	not_found: number,
	pending: number,
};

/**
 *  A station of a list: its Radio-Browser UUID, and the stream of that entry, which also
 *  recognises the other Radio-Browser copies of the station playing the same stream.
 */
export type Item = {
	uuid: string,
	stream?: string | null,
};

export type LikedTrack = {
	track_key: string,
	artist: string | null,
	title: string,
	raw_title: string,
	/**  Station the track was liked on. */
	station_id: string,
	/**  The name the user gave the station, else its name when the track was liked. */
	station_name: string | null,
	liked_at: string,
	search_query: string,
};

/**  What is exported: the whole listening history or the liked tracks. */
export type List = "history" | "likes";

/**  What the station sheet shows of a list the station is in. */
export type ListRef = {
	id: string,
	title: string,
};

export type LocalError = {
	path: string,
	error: string,
};

export type LocalRecipeError = {
	file: string,
	error: string,
};

export type LocalRecipes = {
	folder: string | null,
	/**  Files in the folder, valid or not. */
	count: number,
	errors: LocalRecipeError[],
};

/**  The listener's stored lists that can be exported, like a curated list. */
export type MyList = "favorites" | "my_stations";

/**  What is on air: station name (`icy-name`) and current title. */
export type NowPlaying = {
	station: string | null,
	/**  The title as shown: `Artist - Title` (ICY `StreamTitle`, or rebuilt from `track`). */
	title: string | null,
	/**  Artist and title kept apart, when the source gives them that way. */
	track: TrackInfo | null,
	/**  The track announced next, when the source says. */
	next: TrackInfo | null,
	/**  The show on air, when the source says. */
	show: string | null,
	source: TitleSource | null,
};

export type Origin = 
/**  Shipped with the app. */
"bundled" | 
/**  From the shared list (`getsoundfolk/soundfolk-recipes`), downloaded by the app. */
"shared" | 
/**  In the user's recipes folder. */
"local";

export type PersonalEntry = {
	name: string,
	url: string,
};

/**  Station added by the user (`user:…` ID, private). */
export type PersonalStation = {
	station_id: string,
	name: string,
	stream_url: string,
	genre: string | null,
};

export type PlayOutcome = {
	/**  The frontend must show the click-counting notice (once only). */
	show_click_notice: boolean,
};

/**  State published to the frontend (`{ "status": "error", "message": "…" }`). */
export type PlayerState = { status: "idle" } | { status: "connecting" } | 
/**  The stream dropped after playing: reopening it, or waiting for the network. */
{ status: "reconnecting"; message: string } | { status: "playing" } | { status: "paused" } | { status: "error"; message: string };

/**  Feedback after saving a local recipe. */
export type RecipeNotice = {
	/**  The file name. */
	file: string,
	ok: boolean,
	message: string,
};

export type RecipeRef = {
	id: string,
	name: string,
	origin: Origin,
	path: string | null,
};

/**  What a test reading of a recipe found. */
export type RecipeTest = {
	recipe: RecipeRef | null,
	local_error: LocalError | null,
	/**  The page that was read. */
	url: string | null,
	track: TrackInfo | null,
	next: TrackInfo | null,
	show: string | null,
	/**  The station's UTC offset, in minutes, when the page gives local times. */
	utc_offset_minutes: number | null,
	/**  What went wrong, step by step for the user. */
	error: string | null,
};

/**  The latest release, as `latest.json` describes it. */
export type Release = {
	version: string,
	/**  Its release page, where the packages are. */
	url: string,
};

/**  What the player needs to play a station, whatever its origin. */
export type ResolvedStation = {
	id: string,
	name: string,
	url: string,
	genre: string | null,
};

/**  One page of search results. */
export type SearchPage = {
	stations: Station[],
	/**
	 *  Offset to pass to get the next page, or `None` when the catalog has no more results.
	 *  It counts the catalog's own entries (including the ones filtered out), not `stations.len()`.
	 */
	next_offset: number | null,
};

export type SearchQuery = {
	text?: string | null,
	country_code?: string | null,
	tag?: string | null,
	limit?: number | null,
	offset?: number | null,
};

/**  A link ready to share, and its QR code. */
export type ShareOut = {
	url: string,
	/**  What the link carries: a personal station found in the catalog becomes the catalog's. */
	item: Shared,
	/**
	 *  Stream addresses of stations added by hand that the link carries (said to the sender,
	 *  §4.3).
	 */
	addresses: number,
	/**  Stations added by hand that were looked up in the catalog by their stream address. */
	looked_up: number,
	/**  The QR code as an SVG `data:` address, black on white. */
	qr: string | null,
	/**  Modules on a side, quiet zone included: the image is shown at a multiple of it. */
	qr_modules: number,
};

/**  What a link carries. */
export type Shared = 
/**  A catalog station, by its Radio-Browser UUID. */
{ kind: "station"; id: string } | 
/**  A station added by hand: its name and stream, as the sender had them. */
{ kind: "personal_station"; name: string; url: string } | 
/**  A list published in soundfolk-stations. */
{ kind: "list"; id: string } | 
/**  A listener's own list: catalog stations, then the ones added by hand. */
{ kind: "personal_list"; title: string; stations: string[]; personal: PersonalEntry[] };

/**  A link: what it carries, the track on air when it was sent, and who sent it. */
export type SharedLink = {
	/**  `artist - title`, what was on air when the link was made. */
	track: string | null,
	/**  The sender's name, as they typed it: never a verified identity. */
	from: string | null,
} & Shared;

/**  What *Share this recipe* did. */
export type SharedRecipe = {
	id: string,
	/**  Where the recipe and fixture were saved, as in the repository (`stations/`, `fixtures/`). */
	folder: string,
	/**  The fixture was too long for the link: it is in the clipboard, to paste in the form. */
	fixture_in_clipboard: boolean,
};

/**  A favorite skipped by Next / Previous. */
export type Skipped = {
	/**  Each favorite is skipped once per Next / Previous; two may have the same name. */
	station_id: string,
	name: string,
	/**  Why, as the player said it. */
	reason: string,
};

export type SourceId = "station" | "deezer" | "itunes" | "cover_art_archive";

export type SourceState = 
/**  Nothing playing yet. */
"idle" | 
/**  Web titles are turned off in the settings. */
"off" | 
/**  Looking for a source (waiting for the stream to announce a title, probing the server). */
"searching" | 
/**  The stream announces its titles itself. */
"stream" | "recipe" | "server" | 
/**  No source found. */
"none";

export type Station = {
	id: string,
	name: string,
	url: string,
	homepage: string | null,
	favicon: string | null,
	tags: string[],
	country: string | null,
	country_code: string | null,
	language: string | null,
	codec: string | null,
	bitrate: number,
	votes: number,
	health: Health,
};

export type StationChange = {
	id: string,
	name: string,
	url: string,
	genre: string | null,
	/**  The window must show the click-counting notice (once only). */
	show_click_notice: boolean,
	/**
	 *  Favorites skipped on the way, because they did not broadcast (none when the backend
	 *  retries the same station).
	 */
	skipped: Skipped[],
};

export type StationStats = {
	station_id: string,
	name: string,
	likes: number,
	tracks_heard: number,
	listening_hours: number,
	/**  Likes per hour of listening (`None` without listening time). */
	likes_per_hour: number | null,
	/**  Likes ÷ tracks heard (`None` if no track was heard). */
	like_rate: number | null,
	/**  Plays per distinct track: how often the same tracks come back. */
	repetition: number | null,
	/**  Distinct artists per 100 tracks heard. */
	diversity: number | null,
	/**  Share of titles that could not be split into artist and title (ads, jingles, no metadata). */
	unrecognised_share: number | null,
};

export type Stats = {
	totals: Totals,
	identification: Identification,
	stations: StationStats[],
	artists: Count[],
	albums: Count[],
	/**  Stations that brought artists liked for the first time. */
	discovery_stations: Count[],
	/**  Artists liked for the first time, per month (`YYYY-MM`, local time), oldest first. */
	new_artists_by_month: Count[],
	/**  Tracks heard on several stations (count = number of stations). */
	shared_tracks: Count[],
	/**  Listening hours per day of the week, Monday first (local time). */
	hours_by_weekday: number[],
	/**  Listening hours per hour of the day (local time). */
	hours_by_hour: number[],
	decades: Count[],
	genres: Count[],
	/**  ISO 3166-1 codes. */
	countries: Count[],
};

/**  Where the title comes from (see `docs/08-now-playing.md`). */
export type TitleSource = 
/**  ICY `StreamTitle` in the stream. */
"icy" | 
/**  Tags carried by the stream itself (Ogg / Opus / FLAC Vorbis comments). */
"stream_tags" | 
/**  The station's web page, read with a recipe. */
"recipe" | 
/**  The streaming server's status page (Icecast, Shoutcast, AzuraCast). */
"server";

/**  Where the title of the current playback comes from, for the station sheet. */
export type TitleStatus = {
	state: SourceState,
	/**  The recipe in use, or the one that would be used. */
	recipe: RecipeRef | null,
	/**
	 *  The server status adapter in use (`icecast`, `shoutcast-v2`…); with `Stream`, the one
	 *  giving the details of the stream's titles (`azuracast`).
	 */
	adapter: string | null,
	/**  Why the last reading failed (page unreachable, nothing found…). */
	error: string | null,
	/**  The station's local recipe file exists but cannot be used. */
	local_error: LocalError | null,
};

export type Totals = {
	tracks_heard: number,
	likes: number,
	listening_hours: number,
};

export type TrackInfo = {
	artist: string | null,
	title: string,
	/**  RFC 3339. */
	started_at: string | null,
	duration_secs: number | null,
	cover: string | null,
};

/**  Whether the update check applies to this copy, and whether it is on. */
export type UpdateCheck = {
	supported: boolean,
	enabled: boolean,
};

